import { tv } from "tailwind-variants";

const switchStyle = tv({
  slots: {
    root: [
      "flex h-4 w-8 shrink-0 items-center rounded-full border border-input bg-background p-0.5 transition-all duration-150 ease-default outline-none",
      "focus-visible:ring-2 focus-visible:ring-ring/50",
      "data-checked:bg-primary",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "data-invalid:border-destructive/50",
      "focus-visible:data-invalid:ring-destructive/50",
      "dark:bg-input/15",
      "dark:data-checked:bg-primary",
    ],
    thumb: [
      "flex size-3 items-center justify-center rounded-full bg-foreground transition-all duration-300 ease-default",
      "data-checked:translate-x-3.75 data-checked:bg-primary-foreground",
      "rtl:data-checked:-translate-x-3.75",
      "[&>svg]:size-2 [&>svg]:shrink-0 [&>svg]:text-primary-foreground",
      "dark:[&>svg]:text-primary",
    ],
  },
});

export { switchStyle };

"use client";

import { useDirection } from "@base-ui/react";
import { Switch as BaseSwitch } from "@base-ui/react/switch";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { switchStyle } from "./switch.style";

function Switch({ className, ...props }: BaseSwitch.Root.Props) {
  const direction = useDirection();

  return (
    <BaseSwitch.Root
      data-slot="switch"
      className={mergeSlotClassName(switchStyle().root, className)}
      {...props}
      dir={direction}
    />
  );
}

function SwitchThumb({ className, ...props }: BaseSwitch.Thumb.Props) {
  return (
    <BaseSwitch.Thumb
      data-slot="switch-thumb"
      className={mergeSlotClassName(switchStyle().thumb, className)}
      {...props}
    />
  );
}

export { Switch, SwitchThumb };
